fn encode(message: Vec<char>) -> Vec<char> {
    // Helper function: check if a char is a vowel
    fn is_vowel(c: char) -> bool {
        matches!(c, 'a' | 'e' | 'i' | 'o' | 'u' |
                     'A' | 'E' | 'I' | 'O' | 'U')
    }

    // Helper function: map vowel to corresponding char before case swap
    fn map_vowel(c: char) -> char {
        match c {
            'a' => 'c',
            'e' => 'g',
            'i' => 'k',
            'o' => 'q',
            'u' => 'w',
            'A' => 'C',
            'E' => 'G',
            'I' => 'K',
            'O' => 'Q',
            'U' => 'W',
            _ => c, // not a vowel, should not happen here
        }
    }

    // Helper function: swap case of a letter
    fn swap_case(c: char) -> char {
        if c.is_ascii_lowercase() {
            c.to_ascii_uppercase()
        } else if c.is_ascii_uppercase() {
            c.to_ascii_lowercase()
        } else {
            c
        }
    }

    // Transform each char according to rules
    message.into_iter()
        .map(|c| {
            if c == ' ' {
                // space stays space
                c
            } else if is_vowel(c) {
                // vowel: map then swap case
                let mapped = map_vowel(c);
                swap_case(mapped)
            } else {
                // consonant letter: just swap case
                swap_case(c)
            }
        })
        .collect()
}